using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
namespace DoomSNESed {
    public sealed class GraphicReplacement {public bool Sprite;public int Screen,Id,Width,Height;public byte[] Pixels;public int[] Palette;public byte[] OriginalPixels;public int SizeMode;}
    public sealed class NativeGraphic {
        public bool Sprite;public int Screen,Id,Header,Width,Height;public string Name;
        public override string ToString(){if(Screen>=6)return Name+" - "+Width+" x "+Height+" px";if(Screen>0)return (Screen==1?"Williams logo":Screen==2?"Doom title screen":"Episode "+(Screen-2)+" intermission")+" - 256 x 224 px";return (Sprite?"Sprite frame ":Id<4?"Sky texture ":"Wall texture ")+(Name??Id.ToString())+"       "+Width+"   "+Height+" px";}
    }
    public static class GraphicsAssets {
        public static NativeGraphic Describe(byte[] bytes,bool sprite,int id){int root=RomLayout.At(bytes,sprite?0x1a8000:0x1b0000);int header=root+(sprite?0x1d0:0x7e)+Bin.U16(bytes,root+(sprite?id*2:id));int height=sprite?bytes[header]:bytes[header]&254;if(height==0)height=256;return new NativeGraphic{Sprite=sprite,Id=id,Header=header,Width=bytes[header+1]+(sprite?0:1),Height=height};}
        public static byte CpuBank(int address){return (byte)((address<0x200000?0x40:0xc0)+(address>>16));}
        public static int Address(byte[] b,int p){int bank=b[p+2],addr=Bin.U16(b,p);return bank<64?(bank&63)*0x8000+(addr&32767):(bank&63)*65536+addr;}
        public static byte[] Decode(byte[] bytes,NativeGraphic asset){var pixels=new byte[asset.Width*asset.Height];if(!asset.Sprite&&asset.Id<4){for(int x=0;x<128;x++)for(int y=0;y<128;y++)pixels[y*128+x]=bytes[Address(bytes,asset.Header+2+x*3)+127-y];return pixels;}for(int x=0;x<asset.Width;x++){int p=Address(bytes,asset.Header+2+x*3),y=0;while(y<asset.Height){int value=bytes[p++];if(asset.Sprite){if(value!=0){pixels[(asset.Height-1-y++)*asset.Width+x]=(byte)value;continue;}int run=(sbyte)bytes[p++];if(run==0)break;int count=Math.Min(Math.Abs(run),asset.Height-y);byte colour=run<0?bytes[p++]:(byte)0;while(count-->0)pixels[(asset.Height-1-y++)*asset.Width+x]=colour;}else{int run=(sbyte)value;Bin.Require(run!=0,"Invalid wall column.");int count=Math.Min(Math.Abs(run),asset.Height-y);byte colour=run<0?bytes[p++]:(byte)0;while(count-->0)pixels[(asset.Height-1-y++)*asset.Width+x]=run<0?colour:bytes[p++];}}}return pixels;}
        public static Bitmap Preview(Rom rom,NativeGraphic asset,byte[] pixels){var bitmap=new Bitmap(asset.Width,asset.Height);for(int y=0;y<asset.Height;y++)for(int x=0;x<asset.Width;x++){int index=pixels[y*asset.Width+x];bitmap.SetPixel(x,y,asset.Sprite&&index==0?Color.Transparent:AssetPreview.Palette(rom,index));}return bitmap;}
        public static GraphicReplacement Import(Rom rom,NativeGraphic asset,string path){if(asset.Screen>=6)return HudAssets.Import(rom,asset,path);if(asset.Screen>0)return ScreenAssets.Import(asset,path);using(var bitmap=new Bitmap(path)){Bin.Require(bitmap.Width==asset.Width&&bitmap.Height==asset.Height,"This asset requires exactly "+asset.Width+"   "+asset.Height+" pixels. Resize your image before importing.");var palette=Enumerable.Range(0,256).Select(i=>AssetPreview.Palette(rom,i)).ToArray();var cache=new Dictionary<int,byte>();var pixels=new byte[asset.Width*asset.Height];for(int y=0;y<asset.Height;y++)for(int x=0;x<asset.Width;x++){Color c=bitmap.GetPixel(x,y);if(asset.Sprite&&c.A<128)continue;int rgb=c.ToArgb();byte match;if(!cache.TryGetValue(rgb,out match)){int best=int.MaxValue;for(int i=asset.Sprite?1:0;i<256;i++){Color q=palette[i];int distance=(c.R-q.R)*(c.R-q.R)+(c.G-q.G)*(c.G-q.G)+(c.B-q.B)*(c.B-q.B);if(distance<best){best=distance;match=(byte)i;}}cache[rgb]=match;}pixels[y*asset.Width+x]=match;}return new GraphicReplacement{Sprite=asset.Sprite,Screen=asset.Screen,Id=asset.Id,Width=asset.Width,Height=asset.Height,Pixels=pixels};}}
        public static int Store(byte[] target,byte[] data,List<Section> free,ref int used){Section space=free.Where(s=>s.Size>=data.Length&&(s.Start&65535)+data.Length<=65536).OrderBy(s=>s.Size).FirstOrDefault();Bin.Require(space!=null,"Graphics do not fit in the remaining converted-map allocations.");int address=space.Start;Buffer.BlockCopy(data,0,target,address,data.Length);space.Start+=data.Length;space.Size-=data.Length;used+=data.Length;return address;}
        public static int Apply(Rom rom,byte[] target,List<Section> free){
            var replacements=(rom.Project.Graphics??new List<GraphicReplacement>()).ToList();
            if(rom.Bytes.Length>0x200000)for(int sprite=0;sprite<2;sprite++)foreach(int id in sprite!=0?Enumerable.Range(0,232):Enumerable.Range(2,61).Select(i=>i*2)){var native=Describe(rom.Bytes,sprite!=0,id);if(!replacements.Any(a=>a.Screen==0&&a.Sprite==native.Sprite&&a.Id==id)&&Enumerable.Range(0,native.Width).Any(x=>Address(rom.Bytes,native.Header+2+x*3)>=0x200000))replacements.Add(new GraphicReplacement{Sprite=native.Sprite,Id=id,Width=native.Width,Height=native.Height,Pixels=Decode(rom.Bytes,native)});}
            if(replacements.Count==0)return 0;
            foreach(var asset in replacements.Where(a=>a.Screen==0)){Bin.Require(asset.Sprite?asset.Id>=0&&asset.Id<232:asset.Id==0||rom.WallTextures.Contains(asset.Id),"Unknown replacement asset.");var native=Describe(rom.Bytes,asset.Sprite,asset.Id);Bin.Require(asset.Width==native.Width&&asset.Height==native.Height&&asset.Pixels!=null&&asset.Pixels.Length==native.Width*native.Height,"Invalid replacement dimensions.");}
            int used=0;var plan=new GraphicColumnPlan(rom,replacements);var reclaimed=GraphicStorage.Reclaim(rom,replacements,plan.Retained);if(!plan.Fits(free.Concat(reclaimed))&&plan.Retained.Count>0){var repacked=new GraphicColumnPlan(rom,replacements,false);var allFreed=GraphicStorage.Reclaim(rom,replacements);if(repacked.Fits(free.Concat(allFreed))){plan=repacked;reclaimed=allFreed;}}int reclaimedBytes=reclaimed.Sum(s=>s.Size);rom.Budget.Capacity+=reclaimedBytes;rom.Budget.GraphicsReclaimed+=reclaimedBytes;
            var reused=new HashSet<int>();foreach(var section in plan.Retained)for(int p=section.Start;p<section.Start+section.Size;p++)reused.Add(p);rom.Budget.GraphicsReused+=reused.Count;
            var cpuFree=free.ToList();
            if(!plan.Fits(free.Concat(reclaimed))){int relocation=0;GraphicStorage.ReserveWindow(rom,target,free,ref relocation,true);rom.Budget.Music+=relocation;}
            // Allocate large columns first, matching the fit check. Already-live
            // identical columns stay in place and are excluded from reclamation.
            foreach(var column in plan.Columns.Values.Where(c=>c.Address<0&&c.Parent==null).OrderByDescending(c=>c.Data.Length)){Section space=free.Concat(reclaimed).Where(s=>s.Start<0x200000&&s.Size>=column.Data.Length&&(s.Start&65535)+column.Data.Length<=65536).OrderBy(s=>s.Size).FirstOrDefault();Bin.Require(space!=null,"Wall/sprite graphics do not fit the Super FX 2 MiB address window. More detailed artwork may need more space even at the same dimensions.");column.Address=space.Start;Buffer.BlockCopy(column.Data,0,target,space.Start,column.Data.Length);space.Start+=column.Data.Length;space.Size-=column.Data.Length;used+=column.Data.Length;}
            plan.ResolveContained();
            foreach(var asset in replacements){if(asset.Screen>=6){HudAssets.Apply(target,asset,cpuFree,ref used);continue;}if(asset.Screen>0){ScreenAssets.Apply(rom,target,asset,cpuFree,ref used);continue;}var native=Describe(rom.Bytes,asset.Sprite,asset.Id);if(!asset.Sprite&&asset.Id<4){for(int x=0;x<128;x++)for(int y=0;y<128;y++)target[Address(rom.Bytes,native.Header+2+x*3)+127-y]=asset.Pixels[y*128+x];continue;}for(int x=0;x<asset.Width;x++){int address=plan.Find(asset,x).Address,pointer=native.Header+2+x*3;Bin.W16(target,pointer,address);target[pointer+2]=(byte)(0x40+(address>>16));}}
            free.RemoveAll(s=>!cpuFree.Contains(s));rom.Budget.Graphics=used;return used;
        }
    }
}


